package com.example.knowledgeportal.ai;

/**
 * Citation metadata attached to answers generated by the AI agent.
 */
public class CitationSource {

    private Long documentId;
    private String documentTitle;
    private int documentVersion;
    private String sectionReference;
    private int chunkIndex;
    private String excerpt;

    public CitationSource() {
    }

    public CitationSource(Long documentId, String documentTitle, int documentVersion,
                          String sectionReference, int chunkIndex, String excerpt) {
        this.documentId = documentId;
        this.documentTitle = documentTitle;
        this.documentVersion = documentVersion;
        this.sectionReference = sectionReference;
        this.chunkIndex = chunkIndex;
        this.excerpt = excerpt;
    }

    public Long getDocumentId() {
        return documentId;
    }

    public void setDocumentId(Long documentId) {
        this.documentId = documentId;
    }

    public String getDocumentTitle() {
        return documentTitle;
    }

    public void setDocumentTitle(String documentTitle) {
        this.documentTitle = documentTitle;
    }

    public int getDocumentVersion() {
        return documentVersion;
    }

    public void setDocumentVersion(int documentVersion) {
        this.documentVersion = documentVersion;
    }

    public String getSectionReference() {
        return sectionReference;
    }

    public void setSectionReference(String sectionReference) {
        this.sectionReference = sectionReference;
    }

    public int getChunkIndex() {
        return chunkIndex;
    }

    public void setChunkIndex(int chunkIndex) {
        this.chunkIndex = chunkIndex;
    }

    public String getExcerpt() {
        return excerpt;
    }

    public void setExcerpt(String excerpt) {
        this.excerpt = excerpt;
    }
}
